UPDATE chat_room_read   /*kr.or.ddit.common.webSocket.chat.mapper.IChatMapper.updateLastRead*/
SET last_read_msg_no = #{chatMsgNo}
WHERE chat_room_no = #{chatRoomNo}
  AND chat_member_id = #{chatMemberId}

mapper.insert:
        
            SELECT SEQ_CHAT_MESSAGE.NEXTVAL FROM DUAL
        

        INSERT INTO CHAT_MESSAGE (  /*kr.or.ddit.common.webSocket.chat.vo.ChatMessageVO.insertMessage*/
        CHAT_MSG_NO
        ,CHAT_ROOM_NO
        ,MSG_TY_CD
        ,MSG_CN
        ,CHAT_MEMBER_ID
        ,REG_DTTM
        )
        VALUES (
        #{chatMsgNo}
        ,#{chatRoomNo}
        ,#{msgTyCd}
        ,#{msgCn}
        ,#{chatMemberId}
        ,SYSDATE
        )

mapper.select:
SELECT  CHAT_MEMBER_ID  /*kr.or.ddit.common.webSocket.chat.vo.ChatMessageVO.selectMemberId*/
FROM    CHAT_ROOM_MEMBER
WHERE   CHAT_ROOM_NO = #{chatRoomNo}
  AND   USER_NO = #{userNo}
  AND   LEFT_DTTM IS NULL

mapper.insert:
        INSERT INTO CHAT_ROOM_MEMBER (
            CHAT_MEMBER_ID
            ,CHAT_ROOM_NO
            ,USER_NO
            ,CHATROLE_CD
            ,JOIN_DTTM
        )
        VALUES (
           SEQ_CHAT_ROOM_MEMBER.NEXTVAL
           ,#{chatRoomNo}
           ,#{userNo}
           ,#{chatroleCd}
           ,SYSDATE
       )

INSERT INTO CHAT_ROOM (
    chat_room_no
  , chat_room_nm
  , chat_room_ty_cd
  , reg_dt
  , use_yn
  , rgtr_id
  , chat_joinkey
  , apt_cmplex_no
)VALUES (
    #{chatRoomNo}
    , #{chatRoomNm}
    , #{chatRoomTyCd}
    , SYSDATE
    , 'Y'
    , #{rgtrId}
    , #{chatJoinKey}
    , #{aptCmplexNo}
)
